package org.zhbot.colossal_wyrm_agility;

import net.runelite.api.Client;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.*;

public class ColossalWyrmAgilityPanel extends OverlayPanel {
    private static final long MILLIS_PER_TICK = 600;

    private final Client client;
    private final ColossalWyrmAgilityConfig config;
    private final ProgressBarComponent progressBar = new ProgressBarComponent();

    private Obstacle obstacle = null;
    private int startTick = -1;
    private long startMS = -1;

    @Inject
    private ColossalWyrmAgilityPanel(Client client, ColossalWyrmAgilityConfig config)
    {
        this.client = client;
        this.config = config;

        setPosition(OverlayPosition.TOP_LEFT);
        progressBar.setMinimum(0);
        progressBar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.TEXT_ONLY);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (obstacle == null)
            return null;

        panelComponent.getChildren().clear();

        if (config.overlayPanelTitle())
            panelComponent.getChildren().add(TitleComponent.builder()
                .text(obstacle.getName())
                .color(Color.GREEN)
                .build());

        switch (config.overlayPanelMode())
        {
            case TICKS:
                var ticks = client.getTickCount() - startTick - 1;
                var ticksLeft = obstacle.getTicks() - ticks;

                progressBar.setMaximum(obstacle.getTicks());
                progressBar.setValue(Math.min(ticks, obstacle.getTicks()));
                progressBar.setCenterLabel(ticksLeft + (ticksLeft == 1 ? " tick" : " ticks"));

                break;
            case SECONDS:
                var totalMillis = obstacle.getTicks() * MILLIS_PER_TICK;
                var millis = System.currentTimeMillis() - startMS;
                var millisLeft = totalMillis - millis;

                progressBar.setMaximum(totalMillis);
                progressBar.setValue(Math.min(millis, totalMillis));
                progressBar.setCenterLabel(millisLeft > 0 ? String.format("%.1f seconds", millisLeft / 1000.0) : "Finishing...");
                break;
        }

        panelComponent.getChildren().add(progressBar);

        return super.render(graphics);
    }

    public void setObstacle(Obstacle obstacle)
    {
        this.obstacle = obstacle;
        if (obstacle != null)
        {
            this.startTick = client.getTickCount();
            this.startMS = System.currentTimeMillis();
        }
        else
        {
            this.startTick = -1;
            this.startMS = -1;
        }
    }
}

package org.zhbot.colossal_wyrm_agility;

import com.google.common.collect.ImmutableSet;
import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;

@Getter
public enum Obstacle {
    START_LADDER("Start Ladder", 1, new WorldPoint(1652, 2931, 0), new WorldPoint(1652, 2931, 0)),
    TIGHTROPE("Tightrope", 39, new WorldPoint(1649, 2910, 1), new WorldPoint(1655, 2926, 1)),

    BASIC_TIGHTROPE("Basic Tightrope", 16, new WorldPoint(1635, 2910, 1), new WorldPoint(1647, 2910, 1)),
    ROPE("Rope", 25, new WorldPoint(1627, 2931, 1), new WorldPoint(1632, 2910, 1)),
    BASIC_LADDER("Basic Ladder", 1, new WorldPoint(1626, 2932, 1), new WorldPoint(1626, 2932, 1)),

    ADVANCED_LADDER("Advanced Ladder", 1, new WorldPoint(1648, 2909, 1), new WorldPoint(1648, 2909, 1)),
    EDGE("Edge", 10, new WorldPoint(1635, 2907, 2), new WorldPoint(1647, 2907, 2)),
    ADVANCED_TIGHTROPE("Advanced Tightrope", 56, new WorldPoint(1624, 2931, 2), new WorldPoint(1633, 2908, 2), new WorldPoint(1634, 2908, 2), new WorldPoint(1633, 2907, 2)),
    ZIPLINE("Zipline", 13, new WorldPoint(1645, 2933, 0), new WorldPoint(1625, 2933, 2));

    private final String name;
    private final Set<WorldPoint> startPoints;
    private final WorldPoint endPoint;
    private final int ticks;

    Obstacle(String name, int ticks, WorldPoint endPoint, WorldPoint... startPoints)
    {
        this.name = name;
        this.ticks = ticks;
        this.endPoint = endPoint;
        this.startPoints = ImmutableSet.copyOf(startPoints);
    }

    private static final Map<WorldPoint, Obstacle> START_POINT_MAP = new HashMap<>();
    private static final Map<WorldPoint, Obstacle> END_POINT_MAP = new HashMap<>();

    static
    {
        for (var obstacle : values())
        {
            for (var startPoint : obstacle.startPoints)
                START_POINT_MAP.put(startPoint, obstacle);

            END_POINT_MAP.put(obstacle.endPoint, obstacle);
        }
    }

    public static Obstacle getByStartPoint(WorldPoint point)
    {
        return START_POINT_MAP.get(point);
    }

    public static Obstacle getByEndPoint(WorldPoint point)
    {
        return END_POINT_MAP.get(point);
    }
}

package org.zhbot.colossal_wyrm_agility;

public enum DurationMode {
    TICKS("Ticks"),
    SECONDS("Seconds");

    private final String name;

    DurationMode(String name) {
        this.name = name;
    }

    @Override
    public String toString() {
        return name;
    }
}

package org.zhbot.colossal_wyrm_agility;

import net.runelite.client.config.*;

import java.util.EnumSet;
import java.util.Set;

@ConfigGroup(ColossalWyrmAgilityConfig.group)
public interface ColossalWyrmAgilityConfig extends Config
{
	String group = "colossal-wyrm-agility";

	@ConfigSection(
			name = "Notifications",
			description = "Configure notifications",
			position = 0
	)
	String notificationsSection = "notificationsSection";

	@ConfigItem(
			keyName = "obstacleCompleteNotifications",
			name = "Obstacle Complete",
			description = "Configuration for obstacle complete notifications",
			section = notificationsSection,
			position = 0
	)
	default Notification obstacleCompleteNotifications()
	{
		return Notification.ON;
	}

	@ConfigItem(
			keyName = "enabledObstacles",
			name = "Enabled",
			description = "Which obstacles to give a notification for.",
			section = notificationsSection,
			position = 1
	)
	default Set<Obstacle> enabledObstacles()
	{
		var values = EnumSet.allOf(Obstacle.class);
		values.removeIf(x -> x.getTicks() == 1);
		return values;
	}

	@ConfigSection(
			name = "Overlay panel",
			description = "Configure the overlay panel",
			position = 1
	)
	String overlayPanelSection = "overlayPanelSection";

	@ConfigItem(
			keyName = "overlayPanelEnabled",
			name = "Enabled",
			description = "If the overlay panel should be shown",
			section = overlayPanelSection,
			position = 0
	)
	default boolean overlayPanelEnabled()
	{
		return true;
	}

	@ConfigItem(
			keyName = "overlayPanelTitle",
			name = "Show Title",
			description = "If the overlay panel should have a title showing the current obstacle name",
			section = overlayPanelSection,
			position = 1
	)
	default boolean overlayPanelTitle()
	{
		return true;
	}

	@ConfigItem(
			keyName = "overlayPanelMode",
			name = "Duration Format",
			description = "What format to show an obstacle's duration",
			section = overlayPanelSection,
			position = 1
	)
	default DurationMode overlayPanelMode()
	{
		return DurationMode.TICKS;
	}

	@ConfigSection(
			name = "Chat messages",
			description = "Configure chat messages",
			position = 2
	)
	String chatMessagesSection = "chatMessagesSection";

	@ConfigItem(
			keyName = "hideChatMessages",
			name = "Hide Chat Messages",
			description = "Hide the forced chat messages",
			section = chatMessagesSection,
			position = 0
	)
	default boolean hideChatMessages()
	{
		return true;
	}

	@ConfigItem(
			keyName = "hideChatMessagesOverhead",
			name = "Hide Overhead",
			description = "Hide the forced chat messages overhead",
			section = chatMessagesSection,
			position = 0
	)
	default boolean hideChatMessagesOverhead()
	{
		return true;
	}

	@ConfigItem(
			keyName = "hideLapCount",
			name = "Hide Lap Count",
			description = "Hide the completed lap count message",
			section = chatMessagesSection,
			position = 1
	)
	default boolean hideLapCount()
	{
		return true;
	}

	@ConfigItem(
			keyName = "hideLapDuration",
			name = "Hide Lap Duration",
			description = "Hide the lap duration message",
			section = chatMessagesSection,
			position = 2
	)
	default boolean hideLapDuration()
	{
		return true;
	}

	@ConfigItem(
			keyName = "hideTermites",
			name = "Hide Termites",
			description = "Hide the termite message",
			section = chatMessagesSection,
			position = 3
	)
	default boolean hideTermites()
	{
		return true;
	}

	@ConfigItem(
			keyName = "hideBoneShards",
			name = "Hide Bone Shards",
			description = "Hide the bone shards message",
			section = chatMessagesSection,
			position = 4
	)
	default boolean hideBoneShards()
	{
		return true;
	}
}

package org.zhbot.colossal_wyrm_agility;

import com.google.common.collect.ImmutableSet;
import com.google.gson.Gson;
import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.events.*;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import java.util.EnumSet;
import java.util.Set;

@Slf4j
@PluginDescriptor(
	name = "Colossal Wyrm Agility",
	description = "A plugin to help AFKing Colossal Wyrm Agility.",
	tags = {"colossal", "wyrm", "agility", "afk"}
)
public class ColossalWyrmAgilityPlugin extends Plugin
{
	private static final WorldArea COLOSSAL_WYRM_REMAINS_AREA = new WorldArea(1623, 2905, 35, 31, 0);
	private static final Set<String> CHAT_MESSAGES = ImmutableSet.of(
			"I hope my next adventure is fun.",
			"Nice view.",
			"*sigh*",
			"I wonder what I'll do next.",
			"Boy, my hands are tired.",
			"Why can that anteater talk?",
			"Boy I'm tired."
	);
	private static final String LAP_COUNT_BASIC_MESSAGE = "Your Colossal Wyrm Agility Course (Basic) lap count is: ";
	private static final String LAP_COUNT_ADVANCED_MESSAGE = "Your Colossal Wyrm Agility Course (Advanced) lap count is: ";
	private static final String LAP_DURATION_MESSAGE = "Lap duration: ";
	private static final String TERMITES_MESSAGE = "You managed to scoop up ";
	private static final String BONE_SHARDS_MESSAGE = "You also find";

	@Inject
	private Client client;

	@Inject
	private Notifier notifier;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private ColossalWyrmAgilityConfig config;

	@Inject
	private TextUtils textUtils;

	@Inject
	private ColossalWyrmAgilityPanel panel;

	private boolean inColossalWyrmRemainsArea = false;
	private boolean justLoggedIn = false;

	@Override
	protected void startUp() throws Exception
	{
		migrateConfig();
		updateConfig();
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(panel);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		var player = client.getLocalPlayer();
		if (player == null)
		{
			inColossalWyrmRemainsArea = false;
			return;
		}

		inColossalWyrmRemainsArea = COLOSSAL_WYRM_REMAINS_AREA.contains2D(player.getWorldLocation());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(ColossalWyrmAgilityConfig.group))
			updateConfig();
	}

	private void updateConfig()
	{
		if (config.overlayPanelEnabled())
			overlayManager.add(panel);
		else
			overlayManager.remove(panel);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
			justLoggedIn = true;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (!inColossalWyrmRemainsArea)
			return;

		if (event.getVarbitId() != VarbitID.BUSY)
			return;

		if (justLoggedIn)
		{
			justLoggedIn = false;
			return;
		}

		var player = client.getLocalPlayer();
		if (player == null)
			return;

		var location = player.getWorldLocation();
		if (location == null)
			return;

		if (event.getValue() == 0)
		{
			panel.setObstacle(null);

			var obstacle = Obstacle.getByEndPoint(location);
			if (obstacle == null)
				return;

			if (config.enabledObstacles().contains(obstacle))
				notifier.notify(config.obstacleCompleteNotifications(), "Obstacle \"" + obstacle.getName() + "\" complete");
		}
		else
		{
			var obstacle = Obstacle.getByStartPoint(location);
			if (obstacle == null)
				return;

			if (obstacle.getTicks() > 1)
				panel.setObstacle(obstacle);
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!inColossalWyrmRemainsArea)
			return;

		var message = textUtils.Clean(event.getMessage());

		switch (event.getType())
		{
			case PUBLICCHAT:
				if (!config.hideChatMessages())
					return;

				if (!event.getName().equals(client.getLocalPlayer().getName()))
					return;

				if (!CHAT_MESSAGES.contains(message))
					return;

				break;
			case GAMEMESSAGE:
				if (message.startsWith(LAP_COUNT_BASIC_MESSAGE) || message.startsWith(LAP_COUNT_ADVANCED_MESSAGE))
				{
					if (!config.hideLapCount())
						return;
				}
				else if (message.startsWith(LAP_DURATION_MESSAGE))
				{
					if (!config.hideLapDuration())
						return;
				}
				else if (message.startsWith(TERMITES_MESSAGE))
				{
					if (!config.hideTermites())
						return;
				}
				else if (message.startsWith(BONE_SHARDS_MESSAGE))
				{
					if (!config.hideBoneShards())
						return;
				}
				else
				{
					return;
				}

				break;
			default:
				return;
		}

		final var lineBuffer = client.getChatLineMap().get(event.getType().getType());
		if (lineBuffer == null)
			return;

		lineBuffer.removeMessageNode(event.getMessageNode());
		client.refreshChat();
	}

	@Subscribe
	public void onOverheadTextChanged(OverheadTextChanged event)
	{
		if (!inColossalWyrmRemainsArea)
			return;

		if (!config.hideChatMessagesOverhead())
			return;

		if (!CHAT_MESSAGES.contains(event.getOverheadText()))
			return;

		event.getActor().setOverheadText(null);
	}

	@Provides
	ColossalWyrmAgilityConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ColossalWyrmAgilityConfig.class);
	}

	private void migrateConfig()
	{
		var obstacleMinimumTicks = configManager.getConfiguration(ColossalWyrmAgilityConfig.group, "obstacleMinimumTicks");
		if (obstacleMinimumTicks != null)
		{
			log.debug("Migrating \"obstacleMinimumTicks\". Old value: {}", obstacleMinimumTicks);

			var minimumTicks = Integer.parseInt(obstacleMinimumTicks);
			var obstacles = EnumSet.allOf(Obstacle.class);
			obstacles.removeIf(x -> x.getTicks() < minimumTicks);

			var enabledObstacles = gson.toJson(obstacles);
			configManager.setConfiguration(ColossalWyrmAgilityConfig.group, "enabledObstacles", enabledObstacles);
			log.debug("Migrated to \"enabledObstacles\". New value: {}", enabledObstacles);

			configManager.unsetConfiguration(ColossalWyrmAgilityConfig.group, "obstacleMinimumTicks");
			configManager.sendConfig();
		}
	}
}

package org.zhbot.colossal_wyrm_agility;

import net.runelite.api.Client;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class TextUtils {
    private final Client client;

    @Inject
    private TextUtils(Client client)
    {
        this.client = client;
    }

    public String Clean(String str)
    {
        final var expanded = client.macroExpand(str);
        return Text.removeTags(expanded);
    }
}

